Translate the following Java 11 code to GNU C++11 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Test {
  static PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
  int R, C;
  long[][] binom = new long[61][61];
  int[] cntA = new int[61], cntB = new int[61];
  long best = Long.MAX_VALUE;
  String s;
  Map<Long, Long> memo = new HashMap<>();
  Set<Long> visited = new HashSet<>();

  public static void main(String[] args) {
    new Test().run();
    pw.flush();
  }

  static int readInt() {
    int ans = 0;
    boolean neg = false;
    try {
      boolean started = false;
      for (int c; (c = System.in.read()) != -1; ) {
        if (c == '-') { started = true; neg = true; continue; }
        if (c >= '0' && c <= '9') { started = true; ans = ans * 10 + c - '0'; }
        else if (started) break;
      }
    } catch (IOException e) {}
    return neg ? -ans : ans;
  }

  static long readLong() {
    long ans = 0;
    boolean neg = false;
    try {
      boolean started = false;
      for (int c; (c = System.in.read()) != -1; ) {
        if (c == '-') { started = true; neg = true; continue; }
        if (c >= '0' && c <= '9') { started = true; ans = ans * 10 + c - '0'; }
        else if (started) break;
      }
    } catch (IOException e) {}
    return neg ? -ans : ans;
  }

  static String readString() {
    StringBuilder sb = new StringBuilder();
    try {
      boolean started = false;
      for (int c; (c = System.in.read()) != -1; ) {
        if (!Character.isWhitespace(c)) { started = true; sb.append((char) c); }
        else if (started) break;
      }
    } catch (IOException e) {}
    return sb.toString();
  }

  void dfs(long x, long y, int v1, int v2) {
    long diff = Math.abs(x - y);
    if (best <= 1 || diff - binom[v1][R] * binom[v2][R] >= best) return;
    if (v1 == R - 1 && v2 == R - 1) { if (diff < best) best = diff; return; }
    long key = x * 10000L + v1 * 100L + v2;
    if (visited.contains(key)) return;
    if (v1 >= R) {
      long cur = binom[v1][R] - binom[v1 - 1][R];
      long other = binom[v2][R];
      dfs(x, y + cur * other, v1 - 1, v2);
    }
    if (v2 >= R) {
      long cur = binom[v2][R] - binom[v2 - 1][R];
      long other = binom[v1][R];
      dfs(x + cur * other, y, v1, v2 - 1);
    }
    visited.add(key);
  }

  long solve(long x, long y, int v1, int v2) {
    long diff = Math.abs(x - y);
    if (diff - binom[v1][R] * binom[v2][R] > best) return 0;
    long key = x * 10000L + v1 * 100L + v2;
    Long cached = memo.get(key);
    if (cached != null) return cached;
    if (v1 < R || v2 < R) {
      if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
        int sum = v1 + v2;
        v1 -= cntA[sum];
        v2 -= cntB[sum];
        return binom[v1 + v2][v1];
      }
      return 0;
    }
    long ans = 0;
    char c = s.charAt(v1 + v2 - 1);
    if (c != 'B') {
      long cur = binom[v1][R] - binom[v1 - 1][R];
      long other = binom[v2][R];
      ans += solve(x, y + cur * other, v1 - 1, v2);
    }
    if (c != 'A') {
      long cur = binom[v2][R] - binom[v2 - 1][R];
      long other = binom[v1][R];
      ans += solve(x + cur * other, y, v1, v2 - 1);
    }
    memo.put(key, ans);
    return ans;
  }

  void run() {
    R = readInt();
    C = readInt();
    int maxN = 2 * (R + C);
    for (int i = 0; i <= maxN; i++) {
      binom[i][0] = binom[i][i] = 1;
      for (int j = 1; j < i; j++)
        binom[i][j] = binom[i - 1][j - 1] + binom[i - 1][j];
    }
    long x = 0, y = 0;
    int v1 = R + C, v2 = R + C;
    while (v1 >= R && v2 >= R) {
      if (x > y) {
        long cur = binom[v1][R] - binom[v1 - 1][R];
        long other = binom[v2][R];
        y += cur * other;
        v1--;
      } else {
        long cur = binom[v2][R] - binom[v2 - 1][R];
        long other = binom[v1][R];
        x += cur * other;
        v2--;
      }
    }
    best = Math.abs(x - y);
    dfs(0, 0, R + C, R + C);
    s = readString();
    for (int i = 0; i < 2 * (R + C); i++) {
      cntA[i + 1] = cntA[i] + (s.charAt(i) == 'A' ? 1 : 0);
      cntB[i + 1] = cntB[i] + (s.charAt(i) == 'B' ? 1 : 0);
    }
    long ans = solve(0, 0, R + C, R + C);
    pw.println(ans);
  }
}
